import{_ as d,a0 as a,w as c,s as l,I as n,x as o,a1 as t,A as p,ao as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"一些重要 Docker 命令的簡單介紹 | LCTT x X-CMD","titleTemplate":false,"description":"一些重要 Docker 命令的簡單介紹 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一些重要 Docker 命令的簡單介紹 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一些重要 Docker 命令的簡單介紹 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150413 A Walk Through Some Important Docker Commands","title":"一些重要 Docker 命令的簡單介紹","tag":"201505","desc":""},"relativePath":"201505/20150413 A Walk Through Some Important Docker Commands.md","filePath":"[post].md"}'),s={name:"201505/20150413 A Walk Through Some Important Docker Commands.md"};function k(m,e,h,u,g,D){const r=a("Link");return c(),l("div",null,[e[16]||(e[16]=n("h1",{id:"一些重要-docker-命令的簡單介紹",tabindex:"-1"},[o("一些重要 Docker 命令的簡單介紹 "),n("a",{class:"header-anchor",href:"#一些重要-docker-命令的簡單介紹","aria-label":"Permalink to “一些重要 Docker 命令的簡單介紹”"},"​")],-1)),n("p",null,[e[1]||(e[1]=o("大家好，今天我們來學習一些在你使用 Docker 之前需要了解的重要的 Docker 命令。",-1)),t(r,{href:"https://www.docker.com/"},{default:p(()=>[...e[0]||(e[0]=[o("Docker",-1)])]),_:1}),e[2]||(e[2]=o(" 是一個開源項目，提供了一個可以打包、裝載和運行任何應用的輕量級容器的開放平台。它沒有語言支持、框架和打包系統的限制，從小型的家用電腦到高端服務器，在何時何地都可以運行。這使它們可以不依賴於特定軟件棧和供應商，像一塊塊積木一樣部署和擴展網絡應用、資料庫和後端服務。",-1))]),e[17]||(e[17]=i(`<p>Docker 命令簡單易學，也很容易實現或實踐。這是一些你運行 Docker 並充分利用它需要知道的簡單 Docker 命令。</p><h3 id="_1-拉取-docker-鏡像" tabindex="-1">1. 拉取 Docker 鏡像 <a class="header-anchor" href="#_1-拉取-docker-鏡像" aria-label="Permalink to “1. 拉取 Docker 鏡像”">​</a></h3><p>由於容器是由 Docker 鏡像構建的，首先我們需要拉取一個 docker 鏡像來開始。我們可以從 Docker Registry Hub 獲取所需的 docker 鏡像。在我們使用 pull 命令拉取任何鏡像之前，為了避免 pull 命令的一些惡意風險，我們需要保護我們的系統。為了保護我們的系統不受這個風險影響，我們需要添加 <strong>127.0.0.1 index.docker.io</strong> 到 /etc/hosts 條目。我們可以通過使用喜歡的文本編輯器完成。</p><pre><code># nano /etc/hosts
</code></pre><p>現在，增加下面的一行到文件並保存退出。</p><pre><code>127.0.0.1 index.docker.io
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/docker-hosts.png" alt="Docker 宿主機"></p><p>要拉取一個 docker 鏡像，我們需要運行下面的命令。</p><pre><code># docker pull registry.hub.docker.com/busybox
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/pulling-image.png" alt="Docker pull 命令"></p><p>我們可以檢查本地是否有可用的 Docker 鏡像。</p><pre><code># docker images
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/docker-images.png" alt="Docker 鏡像"></p><h3 id="_2-運行-docker-容器" tabindex="-1">2. 運行 Docker 容器 <a class="header-anchor" href="#_2-運行-docker-容器" aria-label="Permalink to “2. 運行 Docker 容器”">​</a></h3><p>現在，成功地拉取要求的或所需的 Docker 鏡像之後，我們當然想運行這個 Docker 鏡像。我們可以用 docker run 命令在鏡像上運行一個 docker 容器。在 Docker 鏡像上運行一個 docker 容器時我們有很多選項和標記。我們使用 -t 和 -i 選項來運行一個 docker 鏡像並進入容器，如下面所示。</p><pre><code># docker run -it busybox
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/docker-run-shell.png" alt="Docker Run Shell 命令"></p><p>從上面的命令中，我們進入了容器並可以通過交互 shell 訪問它的內容。我們可以鍵入 <strong>Ctrl-D</strong> 從shell中退出。</p><p>現在，在後台運行容器，我們用 -d 標記分離 shell，如下所示。</p><pre><code># docker run -itd busybox
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/run-container-background.png" alt="後台運行容器"></p><p>如果你想進入到一個正在運行的容器，我們可以使用 attach 命令加一個容器 id。可以使用 <strong>docker ps</strong> 命令獲取容器 id。</p><pre><code># docker attach &lt;container id&gt;
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/docker-attach.png" alt="進入Docker"></p><h3 id="_3-檢查容器運行" tabindex="-1">3. 檢查容器運行 <a class="header-anchor" href="#_3-檢查容器運行" aria-label="Permalink to “3. 檢查容器運行”">​</a></h3><p>不論容器是否運行，查看日誌文件都很簡單。我們可以使用下面的命令去檢查是否有 docker 容器在實時運行。</p><pre><code># docker ps
</code></pre><p>現在，查看正在運行的或者之前運行的容器的日誌，我們需要運行以下的命令。</p><pre><code># docker ps -a
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/view-docker-containers1.png" alt="查看 Docker 容器"></p><h3 id="_4-查看容器信息" tabindex="-1">4. 查看容器信息 <a class="header-anchor" href="#_4-查看容器信息" aria-label="Permalink to “4. 查看容器信息”">​</a></h3><p>我們可以使用 inspect 命令查看一個 Docker 容器的各種信息。</p><pre><code># docker inspect &lt;container id&gt;
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/docker-inspect.png" alt="檢查Docker"></p><h3 id="_5-殺死或刪除" tabindex="-1">5. 殺死或刪除 <a class="header-anchor" href="#_5-殺死或刪除" aria-label="Permalink to “5. 殺死或刪除”">​</a></h3><p>我們可以使用容器 id 殺死或者停止 docker 容器（進程），如下所示。</p><pre><code># docker stop &lt;container id&gt;
</code></pre><p>要停止每個正在運行的容器，我們需要運行下面的命令。</p><pre><code># docker kill $(docker ps -q)
</code></pre><p>現在，如我我們希望移除一個 docker 鏡像，運行下面的命令。</p><pre><code># docker rm &lt;container id&gt;
</code></pre><p>如果我們想一次性移除所有 docker 鏡像，我們可以運行以下命令。</p><pre><code># docker rm $(docker ps -aq)
</code></pre><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>這些都是充分學習和使用 Docker 很基本的 docker 命令。有了這些命令，Docker 變得很簡單，可以提供給最終用户一個易用的計算平台。根據上面的教程，任何人學習 Docker 命令都非常簡單。如果你有任何問題，建議，反饋，請寫到下面的評論框中以便我們改進和更新內容。多謝！ 希望你喜歡 😃</p><hr>`,46)),n("p",null,[e[4]||(e[4]=o("via: ",-1)),t(r,{href:"http://linoxide.com/linux-how-to/important-docker-commands/"},{default:p(()=>[...e[3]||(e[3]=[o("http://linoxide.com/linux-how-to/important-docker-commands/",-1)])]),_:1})]),n("p",null,[e[8]||(e[8]=o("作者：",-1)),t(r,{href:"http://linoxide.com/author/arunp/"},{default:p(()=>[...e[5]||(e[5]=[o("Arun Pyasi",-1)])]),_:1}),e[9]||(e[9]=o(" 譯者：",-1)),t(r,{href:"https://github.com/ictlyh"},{default:p(()=>[...e[6]||(e[6]=[o("ictlyh",-1)])]),_:1}),e[10]||(e[10]=o(" 校對：",-1)),t(r,{href:"https://github.com/wxy"},{default:p(()=>[...e[7]||(e[7]=[o("wxy",-1)])]),_:1})]),n("p",null,[e[13]||(e[13]=o("本文由 ",-1)),t(r,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[11]||(e[11]=[o("LCTT",-1)])]),_:1}),e[14]||(e[14]=o(" 原創翻譯，",-1)),t(r,{href:"http://linux.cn/"},{default:p(()=>[...e[12]||(e[12]=[o("Linux中國",-1)])]),_:1}),e[15]||(e[15]=o(" 榮譽推出",-1))])])}const T=d(s,[["render",k]]);export{f as __pageData,T as default};
